import django.db.models.deletion
from django.db import migrations, models
from django.db.models import Sum


def sync_parent_stock(apps, schema_editor):
    """Stok induk = jumlah stok semua varian (sebelumnya hanya varian pertama)."""
    Product = apps.get_model("store", "Product")
    for product in Product.objects.filter(variations__isnull=False).distinct():
        total = product.variations.aggregate(t=Sum("stock"))["t"] or 0
        if product.stock != total:
            Product.objects.filter(pk=product.pk).update(stock=total)


